using System;
using System.Collections.Generic;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CopycatAction", menuName = "Data/Battle/Battle Actions/Orion/Copycat Action")]
public class CopycatAction : ChooseDiceAction
{
	[Header("Action Instance Reference")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnRollDices;

	[NonSerialized]
	private DiceInstance copycatDiceInstance;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0;
	}

	public override void ActionSelected(int amount)
	{
		base.ActionSelected(amount);
		copycatDiceInstance = actionInstanceReference.Value as DiceInstance;
	}

	public override void Cast(GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			CopyDie(source);
			ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(new List<DiceInstance> { copycatDiceInstance }, RollDiceActionType.NONREROLL, source);
		});
	}

	private void CopyDie(GameObject source)
	{
		DiceInstance diceInstance = diceList.First();
		diceList.First().GoBackToOriginalPositionAnimation();
		Dice dice = diceInstance.Dice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		for (int i = 0; i < diceInstance.Dice.GetDiceFaces().Length; i++)
		{
			dice.GetDiceFaces()[i] = new DiceFace(diceInstance.Dice.GetDiceFaces()[i]);
			copycatDiceInstance.Dice.GetDiceFaces()[i] = dice.GetDiceFaces()[i];
			copycatDiceInstance.Dice.GetDiceFaces()[i].UpdateActionValueModifier();
			CompanionAbility component = source.GetComponent<CompanionAbility>();
			if (component != null)
			{
				component.UpdateActionValueModifier();
			}
		}
		copycatDiceInstance.KillTrail();
		copycatDiceInstance.UpdateDiceFace(copycatDiceInstance);
	}
}
